@media (prefers-reduced-motion: reduce) {
  .admin-biometric-settings * {
    scroll-behavior: auto !important;
  }

  .admin-biometric-fingerprint-light-preview i,
  .admin-biometric-enroll-overlay,
  .admin-biometric-enroll-modal,
  .admin-biometric-enroll-modal__glyph-fill {
    animation: none !important;
    transition: none !important;
  }
}

body.admin-biometric-enroll-open {
  overflow: hidden;
}

.admin-biometric-enroll-overlay {
  position: fixed;
  inset: 0;
  z-index: 12100;
  display: grid;
  place-items: center;
  padding: max(16px, env(safe-area-inset-top)) 16px max(16px, env(safe-area-inset-bottom));
  background: rgba(15, 23, 42, 0.28);
  opacity: 0;
  pointer-events: none;
  transition: opacity 180ms ease;
}

.admin-biometric-enroll-overlay.is-open {
  opacity: 1;
  pointer-events: auto;
}

.admin-biometric-enroll-overlay[hidden] {
  display: none !important;
}

.admin-biometric-enroll-modal {
  display: grid;
  width: min(420px, 100%);
  min-height: min(640px, calc(100dvh - 32px));
  grid-template-rows: auto 1fr;
  overflow: hidden;
  border-radius: 28px;
  background: #ffffff;
  box-shadow:
    0 24px 60px rgba(15, 23, 42, 0.16),
    0 2px 8px rgba(15, 23, 42, 0.06);
  color: #111827;
  font-family: "Segoe UI Variable Text", "Segoe UI", system-ui, sans-serif;
  transform: translateY(18px) scale(0.985);
  transition: transform 220ms cubic-bezier(0.22, 1, 0.36, 1);
}

.admin-biometric-enroll-overlay.is-open .admin-biometric-enroll-modal {
  transform: none;
}

.admin-biometric-enroll-modal__header {
  display: grid;
  grid-template-columns: 44px minmax(0, 1fr) auto;
  align-items: center;
  gap: 8px;
  min-height: 56px;
  padding: 10px 14px 6px;
}

.admin-biometric-enroll-modal__header h2 {
  margin: 0;
  color: #111827;
  font-size: 16px;
  font-weight: 600;
  letter-spacing: -0.01em;
  text-align: center;
  line-height: 1.2;
}

.admin-biometric-enroll-modal__back,
.admin-biometric-enroll-modal__cancel {
  appearance: none;
  border: 0;
  background: transparent;
  color: #111827;
  cursor: pointer;
  font: inherit;
}

.admin-biometric-enroll-modal__back {
  width: 40px;
  height: 40px;
  display: grid;
  place-items: center;
  border-radius: 999px;
  color: #111827;
}

.admin-biometric-enroll-modal__back svg {
  width: 22px;
  height: 22px;
}

.admin-biometric-enroll-modal__back:hover,
.admin-biometric-enroll-modal__back:focus-visible {
  background: #f3f4f6;
  outline: none;
}

.admin-biometric-enroll-modal__cancel {
  min-height: 40px;
  padding: 0 8px;
  color: #111827;
  font-size: 15px;
  font-weight: 500;
}

.admin-biometric-enroll-modal__cancel:hover,
.admin-biometric-enroll-modal__cancel:focus-visible {
  color: #2563eb;
  outline: none;
}

.admin-biometric-enroll-modal__body {
  display: grid;
  align-content: start;
  justify-items: center;
  gap: 18px;
  padding: 28px 28px 40px;
  text-align: center;
}

.admin-biometric-enroll-modal__badge {
  display: grid;
  width: 36px;
  height: 36px;
  place-items: center;
  color: #3b9eff;
}

.admin-biometric-enroll-modal__badge svg {
  width: 28px;
  height: 28px;
  stroke-width: 2.1;
}

.admin-biometric-enroll-modal__lead {
  margin: 0;
  max-width: 16rem;
  color: #111827;
  font-size: 18px;
  font-weight: 600;
  letter-spacing: -0.02em;
  line-height: 1.35;
}

.admin-biometric-enroll-modal__glyph {
  position: relative;
  width: min(220px, 58vw);
  aspect-ratio: 1;
  margin: 18px 0 8px;
}

.admin-biometric-enroll-modal__glyph-base,
.admin-biometric-enroll-modal__glyph-fill {
  position: absolute;
  inset: 0;
  display: grid;
  place-items: center;
}

.admin-biometric-enroll-modal__glyph-base {
  color: #1f2937;
}

.admin-biometric-enroll-modal__glyph-fill {
  color: #3b9eff;
  clip-path: inset(0 calc(100% - var(--enroll-progress, 0%)) 0 0);
  transition: clip-path 420ms cubic-bezier(0.22, 1, 0.36, 1);
}

.admin-biometric-enroll-modal__glyph svg {
  width: 100%;
  height: 100%;
  stroke-width: 1.7;
}

.admin-biometric-enroll-modal__hint {
  margin: 0;
  max-width: 17rem;
  color: #6b7280;
  font-size: 13px;
  font-weight: 400;
  line-height: 1.5;
}

.admin-biometric-enroll-modal__steps {
  display: flex;
  gap: 8px;
  margin-top: 8px;
}

.admin-biometric-enroll-modal__steps i {
  width: 8px;
  height: 8px;
  border-radius: 999px;
  background: #e5e7eb;
  transition:
    background-color 220ms ease,
    transform 220ms ease;
}

.admin-biometric-enroll-modal__steps i.is-current {
  background: #93c5fd;
  transform: scale(1.15);
}

.admin-biometric-enroll-modal__steps i.is-done {
  background: #3b9eff;
}

.admin-biometric-enroll-overlay[data-status="success"] .admin-biometric-enroll-modal__badge,
.admin-biometric-enroll-overlay[data-status="success"] .admin-biometric-enroll-modal__glyph-fill {
  color: #16a34a;
}

.admin-biometric-enroll-overlay[data-status="success"] .admin-biometric-enroll-modal__steps i.is-done,
.admin-biometric-enroll-overlay[data-status="success"] .admin-biometric-enroll-modal__steps i.is-current {
  background: #16a34a;
}

.admin-biometric-enroll-overlay[data-status="error"] .admin-biometric-enroll-modal__badge,
.admin-biometric-enroll-overlay[data-status="error"] .admin-biometric-enroll-modal__glyph-fill {
  color: #ef4444;
}

.admin-biometric-enroll-overlay[data-status="error"] .admin-biometric-enroll-modal__lead {
  color: #b91c1c;
}

.admin-biometric-enroll-overlay[data-status="error"] .admin-biometric-enroll-modal__hint {
  color: #dc2626;
}

@media (max-width: 520px) {
  .admin-biometric-enroll-overlay {
    padding: 0;
    place-items: stretch;
  }

  .admin-biometric-enroll-modal {
    width: 100%;
    min-height: 100dvh;
    border-radius: 0;
  }

  .admin-biometric-enroll-modal__body {
    padding-top: 48px;
  }
}
